create table TB_CASH_BALANCE (CASH_ID INT not null  ,TAILBOX_ID VARCHAR(30) null  ,BRANCH VARCHAR(30) null  ,CCY VARCHAR(3) null  ,AMOUNT DECIMAL(17,2) null  ,AVAILABLE_AMT DECIMAL(17,2) null  ,EOPD_AMOUNT DECIMAL(17,2) null  ,SOPD_AMOUNT DECIMAL(17,2) null  ,LOCK_AMOUNT DECIMAL(17,2) null  ,LOCK_SPALL_AMT DECIMAL(17,2) null  ,UPDATE_DATE TIMESTAMP(3) null  ,TRAN_TIMESTAMP VARCHAR(26) null  ,COMPANY VARCHAR(20) null  ,CREATE_TIMESTAMP VARCHAR(26) null  ,LAST_CHANGE_DATE TIMESTAMP(3) null  , primary key(CASH_ID));